# WAR ARENA - GPU Experience Layer (Phase A + B + C) - Installer
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-experience.ps1
# Additive only. Files are Base64-encoded so no content can break PowerShell parsing.
$ErrorActionPreference = "Stop"
$enc = New-Object System.Text.UTF8Encoding($false)
Write-Host "WAR - GPU Experience installer (Phase A+B+C)" -ForegroundColor Cyan

function Write-B64([string]$Path, [string]$B64){
  $dir = Split-Path -Parent $Path
  if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  $bytes = [System.Convert]::FromBase64String($B64)
  [System.IO.File]::WriteAllBytes($Path, $bytes)
  Write-Host "  wrote $Path" -ForegroundColor DarkGray
}

Write-B64 "src/experience/adaptiveQuality.ts" ""
Write-B64 "src/experience/arenaInteraction.ts" ""
Write-B64 "src/experience/cameraAnimator.ts" ""
Write-B64 "src/experience/capability.ts" ""
Write-B64 "src/experience/experienceAdapter.ts" ""
Write-B64 "src/experience/index.ts" ""
Write-B64 "src/experience/inspectorView.ts" ""
Write-B64 "src/experience/liquidityView.ts" ""
