Write-B64 "src/experience/visual/vocabulary.ts" ""
Write-B64 "tsconfig.experience.json" "ewogICJleHRlbmRzIjogIi4vdHNjb25maWcuanNvbiIsCiAgImNvbXBpbGVyT3B0aW9ucyI6IHsKICAgICJsaWIiOiBbIkVTMjAyMiIsICJET00iLCAiRE9NLkl0ZXJhYmxlIl0sCiAgICAidHlwZXMiOiBbXSwKICAgICJub0VtaXQiOiB0cnVlCiAgfSwKICAiaW5jbHVkZSI6IFsic3JjL2V4cGVyaWVuY2UiXSwKICAiZXhjbHVkZSI6IFsibm9kZV9tb2R1bGVzIiwgImRpc3QiXQp9Cg=="
Write-B64 "tests/architecture/experienceBoundaries.test.ts" ""
Write-B64 "tests/unit/experienceCapability.test.ts" ""
Write-B64 "tests/unit/experienceCore.test.ts" ""
Write-B64 "tests/unit/experiencePhaseB.test.ts" ""
Write-B64 "tests/unit/experienceLiquidity.test.ts" ""
