# --- Patch root tsconfig.json: exclude src/experience (idempotent) ---
$tsPath = "tsconfig.json"
$ts = Get-Content $tsPath -Raw
if ($ts -notmatch '"src/experience"') {
  $ts = $ts -replace '("exclude"\s*:\s*\[)([^\]]*)(\])', '$1$2, "src/experience"$3'
  [System.IO.File]::WriteAllText($tsPath, $ts, $enc)
  Write-Host "  patched tsconfig.json exclude -> src/experience" -ForegroundColor DarkGray
} else { Write-Host "  tsconfig.json already excludes src/experience" -ForegroundColor DarkGray }

# --- Patch package.json (idempotent) ---
$pkgPath = "package.json"
$pkg = Get-Content $pkgPath -Raw | ConvertFrom-Json
if (-not $pkg.scripts.'typecheck:experience'){ $pkg.scripts | Add-Member -NotePropertyName 'typecheck:experience' -NotePropertyValue 'tsc -p tsconfig.experience.json' }
if (-not $pkg.dependencies){ $pkg | Add-Member -NotePropertyName 'dependencies' -NotePropertyValue (@{}) }
if (-not $pkg.dependencies.'pixi.js'){ $pkg.dependencies | Add-Member -NotePropertyName 'pixi.js' -NotePropertyValue '^8' }
($pkg | ConvertTo-Json -Depth 20) | Set-Content -Path $pkgPath -Encoding utf8
Write-Host "  patched package.json (script + pixi.js dep)" -ForegroundColor DarkGray

Write-Host ""; Write-Host "Installing deps (pixi.js@8) ..." -ForegroundColor Cyan
npm install
Write-Host ""; Write-Host "Verifying gate ..." -ForegroundColor Cyan
npx tsc --noEmit; if ($LASTEXITCODE -ne 0){ throw "root typecheck failed" }
npx tsc -p tsconfig.experience.json; if ($LASTEXITCODE -ne 0){ throw "experience typecheck failed" }
npx vitest run; if ($LASTEXITCODE -ne 0){ throw "tests failed" }
Write-Host ""; Write-Host "GPU Experience layer installed and verified." -ForegroundColor Green
Write-Host "Expected: 790 passed + 1 skipped, 367 guards, typecheck clean." -ForegroundColor Yellow
